<template>
  <main class="checkout-page" :aria-busy="loading || creating || paying ? 'true' : 'false'">
    <header class="page-header">
      <div><p>{{ $t('checkout.kicker') }}</p><h1>{{ $t('checkout.title') }}</h1><span>{{ $t('checkout.subtitle') }}</span></div>
      <router-link class="secondary-action" to="/workspace/cart"><i class="el-icon-back"></i>{{ $t('checkout.back') }}</router-link>
    </header>

    <section v-if="loading" class="state-card"><i class="el-icon-loading"></i><h2>{{ $t('checkout.loading') }}</h2></section>
    <section v-else-if="error && !createdOrder" class="state-card error"><i class="el-icon-warning-outline"></i><h2>{{ $t('checkout.errorTitle') }}</h2><p>{{ error }}</p><button type="button" @click="initialize">{{ $t('common.retry') }}</button></section>

    <section v-else-if="paymentComplete" class="success-card"><span><i class="el-icon-check"></i></span><p>{{ $t('checkout.created') }} · {{ createdOrder.number }}</p><h2>{{ $t('checkout.successTitle') }}</h2><p>{{ $t('checkout.successCopy') }}</p><router-link to="/main/dashboard">{{ $t('checkout.done') }}</router-link></section>

    <section v-else-if="createdOrder" class="payment-layout">
      <div class="payment-card"><span class="success-mark"><i class="el-icon-check"></i></span><p>{{ $t('checkout.created') }}</p><h2>{{ $t('checkout.paymentTitle') }}</h2><span>{{ $t('checkout.paymentCopy') }}</span><dl><div><dt>{{ $t('checkout.orderNumber') }}</dt><dd>{{ createdOrder.number }}</dd></div><div><dt>{{ $t('checkout.total') }}</dt><dd>{{ money(createdOrder.cost) }}</dd></div></dl></div>
      <aside class="payment-options">
        <label v-for="method in paymentMethods" :key="method.value" :class="{ selected: paymentMethod === method.value }"><input v-model="paymentMethod" type="radio" :value="method.value" /><span><strong>{{ method.label }}</strong><small v-if="method.value !== 2">{{ $t('checkout.externalPayment') }}</small></span></label>
        <p v-if="actionError" class="action-error">{{ actionError }}</p>
        <button class="primary-action" type="button" :disabled="paying" @click="payOrderNow">{{ paying ? $t('checkout.paying') : $t('checkout.pay') }}</button>
      </aside>
    </section>

    <div v-else class="checkout-layout">
      <div class="checkout-main">
        <section class="panel address-panel">
          <div class="section-heading"><div><h2>1. {{ $t('checkout.address') }}</h2><p>{{ $t('checkout.addressCopy') }}</p></div><router-link to="/account/shippingAddresses">{{ $t('checkout.manageAddress') }}</router-link></div>
          <label v-if="addresses.length" class="select-field"><span>{{ $t('checkout.chooseAddress') }}</span><select v-model="selectedAddressId" @change="loadPreview"><option v-for="address in addresses" :key="address.id" :value="String(address.id)">{{ addressLabel(address) }}</option></select></label>
          <div v-else class="empty-address"><i class="el-icon-location-outline"></i><span>{{ $t('checkout.noAddress') }}</span><router-link to="/account/shippingAddresses">{{ $t('checkout.manageAddress') }}</router-link></div>
        </section>

        <section class="panel items-panel">
          <div class="section-heading"><div><h2>2. {{ $t('checkout.items') }}</h2><p>{{ $t('checkout.itemsCopy') }}</p></div><button type="button" :disabled="loading" @click="loadPreview">{{ $t('checkout.recalculate') }}</button></div>
          <article v-for="(order,index) in previewOrders" :key="order.cart_id || index" class="order-group">
            <div v-for="product in goodsFor(order)" :key="product.goods_id || product.subject" class="product-block">
              <div v-for="(sku,skuIndex) in product.sku_info || []" :key="sku.id || skuIndex" class="sku-row"><img :src="sku.image || product.image" :alt="product.subject" /><span><strong>{{ product.subject }}</strong><small>{{ sku.sku_name || $t('checkout.variant') }}</small></span><span class="sku-qty">{{ $t('checkout.quantity') }} {{ sku.num }}</span><strong>{{ money(sku.total_price_us || Number(sku.price_us || 0) * Number(sku.num || 0)) }}</strong></div>
            </div>
            <label v-if="freightOptions(order).length" class="freight-field"><span>{{ $t('checkout.shipping') }}</span><select :value="selectedFreight(order)" :disabled="shippingUpdating" @change="changeFreight(order,$event.target.value)"><option v-for="freight in freightOptions(order)" :key="freight.vendor_code" :value="freight.vendor_code">{{ freight.product_name_e || freight.product_name }}, {{ money(freight.freight) }}, {{ freight.aging_start }}-{{ freight.aging_end }} days</option></select></label>
          </article>
          <label class="note-field"><span>{{ $t('checkout.remark') }}</span><textarea v-model.trim="remark" rows="3" :placeholder="$t('checkout.remarkPlaceholder')"></textarea></label>
        </section>
      </div>

      <aside class="summary-card">
        <h2>{{ $t('checkout.summary') }}</h2>
        <dl><div><dt>{{ $t('checkout.productCost') }}</dt><dd>{{ money(totals.products) }}</dd></div><div><dt>{{ $t('checkout.shippingCost') }}</dt><dd>{{ money(totals.shipping) }}</dd></div><div v-if="coupons.length" class="coupon-row"><dt>{{ $t('checkout.coupon') }}</dt><dd><select v-model="selectedCouponId"><option value="">{{ $t('checkout.noCoupon') }}</option><option v-for="coupon in coupons" :key="coupon.id" :value="String(coupon.id)" :disabled="!couponAvailable(coupon)">{{ couponLabel(coupon) }}</option></select></dd></div><div v-if="couponDiscount"><dt>{{ $t('checkout.discount') }}</dt><dd>-{{ money(couponDiscount) }}</dd></div><div class="grand-total"><dt>{{ $t('checkout.total') }}</dt><dd>{{ money(payableTotal) }}</dd></div></dl>
        <label class="review-check"><input v-model="reviewed" type="checkbox" /><span>{{ $t('checkout.disclaimer') }}</span></label>
        <p v-if="actionError" class="action-error">{{ actionError }}</p>
        <button class="primary-action" type="button" :disabled="creating || !addresses.length || !previewOrders.length" @click="createOrder">{{ creating ? $t('checkout.creating') : $t('checkout.create') }}</button>
      </aside>
    </div>
  </main>
</template>

<script>
import { reqGetAddress } from '@/api/address'
import { orderInfo, orderCreate, orderPay, updateFreightCode } from '@/api/dropshipping'

export default {
  name: 'WorkspaceCheckout',
  data() { return { loading: true, creating: false, paying: false, shippingUpdating: false, error: '', actionError: '', addresses: [], selectedAddressId: '', previewOrders: [], totals: { products: 0, shipping: 0, total: 0 }, coupons: [], selectedCouponId: '', remark: '', reviewed: false, createdOrder: null, paymentComplete: false, paymentMethod: 2 } },
  computed: {
    account() { try { return JSON.parse(localStorage.getItem('userInfo') || '{}') } catch { return {} } },
    requestPayload() { const address = this.addresses.find((item) => String(item.id) === String(this.selectedAddressId)); const goodsSkuAndNum = this.parseSkuQuery().map((item) => ({ ...item, delivery_area_code: item.delivery_area_code || address?.country || '' })); return { preview_type: this.$route.query.offerId ? '1' : '2', give_address_id: this.selectedAddressId || null, is_freight_agency: 1, price_control_id: null, shipping_fee: null, cart_info_ids: String(this.$route.query.cartIds || ''), source: String(this.$route.query.source || '1'), goodsId: this.$route.query.offerId || '', goodsSkuAndNum } },
    selectedCoupon() { return this.coupons.find((coupon) => String(coupon.id) === String(this.selectedCouponId)) || null },
    couponDiscount() { return this.selectedCoupon && this.couponAvailable(this.selectedCoupon) ? this.number(this.selectedCoupon.type_value) : 0 },
    payableTotal() { return Math.max(0, Number(this.totals.total || 0) - Number(this.couponDiscount || 0)) },
    paymentMethods() { return [{ value: 2, label: this.$t('checkout.wallet') }, { value: 3, label: this.$t('checkout.card') }, { value: 4, label: this.$t('checkout.paypal') }] },
  },
  mounted() { this.initialize() },
  methods: {
    parseSkuQuery() { if (!this.$route.query.sku) return []; try { const value = JSON.parse(decodeURIComponent(this.$route.query.sku)); return Array.isArray(value) ? value : [] } catch { return [] } },
    async initialize() { this.loading = true; this.error = ''; this.actionError = ''; try { const response = await reqGetAddress({ email: this.account.email }); this.addresses = Array.isArray(response?.data) ? response.data : []; const preferred = this.addresses.find((item) => String(item.is_default) === '1') || this.addresses[0]; this.selectedAddressId = preferred ? String(preferred.id) : ''; if (this.selectedAddressId) await this.loadPreview(false) } catch (error) { this.error = error?.message || this.$t('checkout.errorTitle') } finally { this.loading = false } },
    async loadPreview(manageLoading = true) { if (!this.selectedAddressId) return; if (manageLoading) this.loading = true; this.error = ''; this.actionError = ''; try { const response = await orderInfo(this.requestPayload); if (Number(response?.code) !== 0) throw new Error(response?.msg || this.$t('checkout.errorTitle')); const data = response.data || {}; this.previewOrders = Array.isArray(data.orders) ? data.orders : []; this.coupons = Array.isArray(data.coupon_list) ? data.coupon_list : []; if (this.selectedCouponId && !this.coupons.some((coupon) => String(coupon.id) === String(this.selectedCouponId) && this.couponAvailable(coupon))) this.selectedCouponId = ''; this.totals = { products: this.number(data.total_purchase_fee ?? data.total_price_us), shipping: this.number(data.total_shipping_fee), total: this.number(data.total_price) }; if (!this.totals.total) this.totals.total = this.totals.products + this.totals.shipping } catch (error) { this.error = error?.message || this.$t('checkout.errorTitle') } finally { if (manageLoading) this.loading = false } },
    goodsFor(order) { return order?.order_info?.goods_list || [] },
    freightOptions(order) { return order?.order_info?.freight_info || [] },
    selectedFreight(order) { return order?.order_info?.default_freight?.vendor_code || this.freightOptions(order)[0]?.vendor_code || '' },
    async changeFreight(order, freightCode) { if (!order?.cart_id || !freightCode) return; this.shippingUpdating = true; this.actionError = ''; try { const response = await updateFreightCode({ cart_id: order.cart_id, freight_code: freightCode }); if (Number(response?.code) !== 0) throw new Error(response?.msg); await this.loadPreview(false) } catch (error) { this.actionError = error?.message || this.$t('checkout.errorTitle') } finally { this.shippingUpdating = false } },
    async createOrder() { this.actionError = ''; if (!this.selectedAddressId) { this.actionError = this.$t('checkout.addressRequired'); return } if (!this.reviewed) { this.actionError = this.$t('checkout.reviewRequired'); return } this.creating = true; try { const payload = { ...this.requestPayload, purchase_type: this.requestPayload.preview_type, order_remark: this.remark, give_address_id: this.selectedAddressId, coupon_id: this.selectedCouponId }; const response = await orderCreate(JSON.stringify(payload)); if (Number(response?.code) !== 0) throw new Error(response?.msg || this.$t('checkout.errorTitle')); this.createdOrder = { number: response?.data?.order_number, cost: this.payableTotal } } catch (error) { this.actionError = error?.message || this.$t('checkout.errorTitle') } finally { this.creating = false } },
    async payOrderNow() { if (!this.createdOrder?.number) return; this.paying = true; this.actionError = ''; try { const response = await orderPay({ order_number: this.createdOrder.number, payment_method: this.paymentMethod, client_type: 1, type: 1 }); if (Number(response?.code) !== 0) throw new Error(response?.msg || this.$t('checkout.errorTitle')); const url = response?.data?.url; if (url) window.location.assign(url); else this.paymentComplete = true } catch (error) { this.actionError = error?.message || this.$t('checkout.errorTitle') } finally { this.paying = false } },
    addressLabel(address) { return [address.full_name, address.address_one, address.city, address.area, address.country_name || address.country].filter(Boolean).join(', ') },
    couponAvailable(coupon) { const minimum = this.number(coupon.min_price); return !minimum || this.number(this.totals.total) >= minimum },
    couponLabel(coupon) { const amount = this.money(coupon.type_value); const minimum = this.number(coupon.min_price); return minimum ? `${amount} · ${this.$t('checkout.minimum', { amount: this.money(minimum) })}` : amount },
    number(value) { const number = Number(String(value ?? 0).replace(/[^0-9.-]/g, '')); return Number.isFinite(number) ? number : 0 },
    money(value) { return new Intl.NumberFormat(this.$workspaceLocale.locale || 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 }).format(this.number(value)) },
  },
}
</script>

<style scoped>
.checkout-page{max-width:1480px;margin:0 auto;padding:38px 34px 70px;color:#202522;font-size:16px}.page-header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:25px}.page-header p{margin:0 0 7px;color:#b34720;font-size:13px;font-weight:900}.page-header h1{margin:0;font-size:clamp(30px,3vw,42px);letter-spacing:-.035em}.page-header span{display:block;max-width:760px;margin-top:9px;color:#69716b;line-height:1.55}.secondary-action,.primary-action{min-height:44px;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:0 17px;border-radius:9px;font-weight:800}.secondary-action{border:1px solid #cfd5cf;background:#fff;color:#323934}.primary-action{width:100%;border:0;background:#dc5221;color:#fff;cursor:pointer}.primary-action:disabled{cursor:not-allowed;opacity:.55}.checkout-layout{display:grid;grid-template-columns:minmax(0,1fr) 390px;align-items:start;gap:20px}.checkout-main{display:grid;gap:18px}.panel,.summary-card,.payment-card,.payment-options,.state-card,.success-card{border:1px solid #dce2dc;border-radius:13px;background:#fff;box-shadow:0 14px 35px rgba(32,45,35,.045)}.panel{padding:24px}.section-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding-bottom:19px;border-bottom:1px solid #e2e6e2}.section-heading h2{margin:0;font-size:21px}.section-heading p{margin:6px 0 0;color:#6c756e;font-size:14px}.section-heading a,.section-heading button{border:0;background:transparent;color:#b34720;font-weight:800;cursor:pointer}.select-field,.note-field{display:grid;gap:8px;margin-top:20px;color:#4e5750;font-weight:700}.select-field select,.freight-field select{width:100%;height:46px;padding:0 12px;border:1px solid #d3d9d3;border-radius:8px;background:#fff}.empty-address{min-height:90px;display:flex;align-items:center;gap:12px;margin-top:18px;padding:16px;border-radius:9px;background:#f4f6f3;color:#667068}.empty-address a{margin-left:auto;color:#b34720;font-weight:800}.order-group{padding:18px 0;border-bottom:1px solid #e2e6e2}.order-group:last-of-type{border-bottom:0}.sku-row{min-height:82px;display:grid;grid-template-columns:60px minmax(0,1fr) 90px 100px;align-items:center;gap:14px}.sku-row img{width:58px;height:58px;border-radius:8px;object-fit:cover;background:#f2f4f1}.sku-row span strong,.sku-row span small{display:block}.sku-row span strong{font-size:14px}.sku-row span small{margin-top:5px;color:#747d76;font-size:12px}.sku-row>strong{text-align:right}.sku-qty{color:#5e675f;font-size:13px}.freight-field{display:grid;grid-template-columns:150px minmax(0,1fr);align-items:center;gap:14px;margin-top:10px;padding:14px;border-radius:9px;background:#f5f7f4;font-weight:800}.note-field textarea{padding:12px;border:1px solid #d3d9d3;border-radius:8px;resize:vertical}.summary-card{position:sticky;top:92px;padding:24px}.summary-card h2{margin:0 0 20px;font-size:22px}.summary-card dl{margin:0}.summary-card dl>div{display:flex;justify-content:space-between;gap:18px;padding:13px 0;border-bottom:1px solid #e3e7e3}.summary-card dt{color:#667068}.summary-card dd{margin:0;font-weight:800}.summary-card .grand-total{align-items:end;padding:20px 0}.grand-total dd{color:#d64d1e;font-size:25px}.review-check{display:flex;align-items:flex-start;gap:10px;margin:20px 0;color:#626b64;font-size:13px;line-height:1.45}.review-check input{width:17px;height:17px;flex:0 0 auto;accent-color:#df5523}.action-error{padding:11px;border-radius:8px;background:#fff0ea;color:#9d3d1d;font-size:13px}.state-card,.success-card{min-height:430px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px;text-align:center}.state-card>i{font-size:30px;color:#dd5422}.state-card button,.success-card a{min-height:42px;display:inline-flex;align-items:center;padding:0 18px;border:0;border-radius:8px;background:#df5523;color:#fff;font-weight:800}.payment-layout{display:grid;grid-template-columns:minmax(0,1fr) 420px;gap:20px}.payment-card,.payment-options{padding:30px}.success-mark,.success-card>span{width:52px;height:52px;display:grid;place-items:center;border-radius:14px;background:#e8f4ec;color:#26734e;font-size:23px}.payment-card h2{font-size:30px}.payment-card>p{color:#25734e;font-weight:900}.payment-card>span:not(.success-mark){color:#6b746d}.payment-card dl{margin-top:30px}.payment-card dl>div{display:flex;justify-content:space-between;padding:14px 0;border-top:1px solid #e1e5e1}.payment-options{display:grid;gap:12px}.payment-options label{min-height:68px;display:flex;align-items:center;gap:12px;padding:13px;border:1px solid #d8ddd8;border-radius:9px;cursor:pointer}.payment-options label.selected{border-color:#df5523;background:#fff7f2}.payment-options label span strong,.payment-options label span small{display:block}.payment-options label span small{margin-top:4px;color:#747d76;font-size:11px}@media(max-width:1050px){.checkout-layout,.payment-layout{grid-template-columns:1fr}.summary-card{position:static}}@media(max-width:700px){.checkout-page{padding:26px 16px 50px}.page-header{display:block}.page-header .secondary-action{margin-top:18px}.panel{padding:18px}.sku-row{grid-template-columns:54px minmax(0,1fr);}.sku-row>.sku-qty,.sku-row>strong{grid-column:2;text-align:left}.freight-field{grid-template-columns:1fr}}
.coupon-row{align-items:center}.coupon-row dd{max-width:205px}.coupon-row select{width:100%;min-height:38px;padding:0 8px;border:1px solid #d3d9d3;border-radius:7px;background:#fff;color:#333a35}
</style>
